    public async Task<IResult> ConfirmRecovery(HttpContext ctx, CancellationToken ct) { var body = await Body(ctx, ct, "challengeId", "recoveryCode", "requestNonce"); var code = Text(body, "recoveryCode"); if (code.Length != 32 || code.Any(c => !char.IsAsciiHexDigit(c))) throw ProofInvalid(); await using var w = await Start(ct); var u = await Load(w, ctx, ct) ?? throw new M0Exception(401, "AUTHENTICATION_REQUIRED"); await MfaThrottle(w, ctx, u, false, ct); var c = await w.Read("m0.security_load_challenge", ct, ("@ChallengeId", Text(body, "challengeId")), ("@SessionId", S(u, "SessionId")), ("@Intent", "recovery"), ("@Now", Now)); if (c is null) throw ProofInvalid(); try { var id = M0Http.Id("session"); await w.Run("m0.security_accept_recovery", ct, ("@UserId", S(u, "UserId")), ("@SessionId", S(u, "SessionId")), ("@ChallengeId", S(c, "ChallengeId")), ("@Nonce", Text(body, "requestNonce")), ("@CodeHash", M0Http.Hash(code.ToLowerInvariant())), ("@Now", Now), ("@NewSessionId", id), ("@NewNonce", M0Http.Id("nonce"))); var next = await w.Read("m0.security_load_session", ct, ("@SessionId", id), ("@Now", Now)) ?? throw ProofInvalid(); await w.Commit(ct); Issue(ctx, next); return M0Http.Json(ctx, new { stage = "RecoveryRebind", permissions = Array.Empty<string>(), expiresAt = S(next, "ExpiresAt"), version = SecurityRules.Version(N(next, "MfaVersion")) }); } catch (SqlException ex) when (ex.Number == 51004) { await MfaThrottle(w, ctx, u, true, ct); await w.Run("m0.security_fail_challenge", ct, ("@ChallengeId", S(c, "ChallengeId"))); await w.Commit(ct); throw ProofInvalid(); } }
    object GrantModel(JsonObject g) => new { id = S(g, "GrantId"), targetUserId = S(g, "UserId"), role = S(g, "Role"), permission = S(g, "Permission"), scope = new { kind = S(g, "ScopeKind"), id = S(g, "ScopeId") }, validFrom = S(g, "ValidFrom"), validUntil = S(g, "ValidUntil"), reason = S(g, "Reason"), grantedBy = S(g, "GrantedBy"), revokedAt = g["RevokedAt"]?.GetValue<string>(), version = SecurityRules.Version(N(g, "Version")), etag = SecurityRules.ETag("Grant", S(g, "GrantId"), N(g, "Version")) };
    public async Task<IResult> GetGrant(HttpContext ctx, string id, CancellationToken ct) { SecurityRules.Identifier(id); await using var w = await Start(ct); var u = await Load(w, ctx, ct) ?? throw new M0Exception(401, "AUTHENTICATION_REQUIRED"); var grant = await w.Read("m0.security_get_grant", ct, ("@GrantId", id)) ?? throw new M0Exception(404, "RESOURCE_NOT_FOUND"); await Authorize(u, "access.read", "User", S(grant, "UserId"), null, ct); if (!SecurityRules.IsCorePermission(S(grant, "Permission"))) throw new M0Exception(404, "RESOURCE_NOT_FOUND"); await w.Commit(ct); ctx.Response.Headers.ETag = SecurityRules.ETag("Grant", id, N(grant, "Version")); return M0Http.Json(ctx, GrantModel(grant)); }
    public async Task<IResult> RevokeGrant(HttpContext ctx, string id, CancellationToken ct)
    {
        SecurityRules.Identifier(id);
        var key = M0Http.Key(ctx);
        var reason = ctx.Request.Headers["X-Change-Reason"].ToString();
        if (reason.Length is < 1 or > 500 || reason.Contains('\r') || reason.Contains('\n')) throw new M0Exception(422, "VALIDATION_ERROR");
        var fingerprint = M0Http.Hash(JsonSerializer.Serialize(new { id, reason, ifMatch = ctx.Request.Headers.IfMatch.ToString(), dataset = sql.Settings.DatasetId }));
        await using var w = await Start(ct);
        var u = await Load(w, ctx, ct) ?? throw new M0Exception(401, "AUTHENTICATION_REQUIRED");
        var grant = await w.Read("m0.security_get_grant", ct, ("@GrantId", id)) ?? throw new M0Exception(404, "RESOURCE_NOT_FOUND");
        await Authorize(u, "access.manage", "User", S(grant, "UserId"), "access.manage", ct);
        if (!SecurityRules.IsCorePermission(S(grant, "Permission"))) throw new M0Exception(404, "RESOURCE_NOT_FOUND");
        var replay = await w.Read("m0.security_get_replay", ct, ("@Actor", S(u, "UserId")), ("@Key", key));
        if (replay is not null)
        {
            if (S(replay, "Fingerprint") != fingerprint) throw new M0Exception(409, "KEY_CONFLICT");
            await w.Commit(ct);
            return Results.NoContent();
        }
        SecurityRules.Match(ctx, "Grant", id, N(grant, "Version"));
        await w.Run("m0.security_revoke_grant", ct, ("@GrantId", id), ("@Actor", S(u, "UserId")), ("@ActorSessionId", S(u,"SessionId")), ("@ActorSecurityVersion", N(u,"SecurityVersion")), ("@Version", N(grant, "Version")), ("@Reason", reason), ("@Now", Now));
        await w.Run("m0.security_record_replay", ct, ("@Actor", S(u, "UserId")), ("@Key", key), ("@Fingerprint", fingerprint), ("@Now", Now));
        await w.Commit(ct);
        return Results.NoContent();
    }
